163	//! An iterator over lattice universes.
164	//==============================================================================
165	
166	class LatticeIter {
167	public:
168	  int indx_; //!< An index to a Lattice universes or offsets array.
169	
170	  LatticeIter(Lattice& lat, int indx) : indx_(indx), lat_(lat) {}
171	
172	  bool operator==(const LatticeIter& rhs) { return (indx_ == rhs.indx_); }
173	
174	  bool operator!=(const LatticeIter& rhs) { return !(*this == rhs); }
175	
176	  int32_t& operator*() { return lat_.universes_[indx_]; }
177	
178	  LatticeIter& operator++()
179	  {
180	    while (indx_ < lat_.end().indx_) {
181	      ++indx_;
182	      if (lat_.is_valid_index(indx_))
183	        return *this;
184	    }
185	    indx_ = lat_.end().indx_;
186	    return *this;
187	  }
188	
189	protected:
190	  Lattice& lat_;
191	};
