193	//==============================================================================
194	//! A reverse iterator over lattice universes.
195	//==============================================================================
196	
197	class ReverseLatticeIter : public LatticeIter {
198	public:
199	  ReverseLatticeIter(Lattice& lat, int indx) : LatticeIter {lat, indx} {}
200	
201	  ReverseLatticeIter& operator++()
202	  {
203	    while (indx_ > lat_.begin().indx_ - 1) {
204	      --indx_;
205	      if (lat_.is_valid_index(indx_))
206	        return *this;
207	    }
208	    indx_ = -1;
209	    return *this;
210	  }
211	};
