133	void Lattice::to_hdf5(hid_t lattices_group) const
134	{
135	  // Make a group for the lattice.
136	  std::string group_name {"lattice "};
137	  group_name += std::to_string(id_);
138	  hid_t lat_group = create_group(lattices_group, group_name);
139	
140	  // Write the name and outer universe.
141	  if (!name_.empty()) {
142	    write_string(lat_group, "name", name_, false);
143	  }
144	
145	  if (outer_ != NO_OUTER_UNIVERSE) {
146	    int32_t outer_id = model::universes[outer_]->id_;
147	    write_dataset(lat_group, "outer", outer_id);
148	  } else {
149	    write_dataset(lat_group, "outer", outer_);
150	  }
151	
152	  // Call subclass-overriden function to fill in other details.
153	  to_hdf5_inner(lat_group);
154	
155	  close_group(lat_group);
156	}
