395	
396	void RectLattice::to_hdf5_inner(hid_t lat_group) const
397	{
398	  // Write basic lattice information.
399	  write_string(lat_group, "type", "rectangular", false);
400	  if (is_3d_) {
401	    write_dataset(lat_group, "pitch", pitch_);
402	    write_dataset(lat_group, "lower_left", lower_left_);
403	    write_dataset(lat_group, "dimension", n_cells_);
404	  } else {
405	    array<double, 2> pitch_short {{pitch_[0], pitch_[1]}};
406	    write_dataset(lat_group, "pitch", pitch_short);
407	    array<double, 2> ll_short {{lower_left_[0], lower_left_[1]}};
408	    write_dataset(lat_group, "lower_left", ll_short);
409	    array<int, 2> nc_short {{n_cells_[0], n_cells_[1]}};
410	    write_dataset(lat_group, "dimension", nc_short);
411	  }
412	
413	  // Write the universe ids.  The convention here is to switch the ordering on
414	  // the y-axis to match the way universes are input in a text file.
415	  if (is_3d_) {
416	    hsize_t nx {static_cast<hsize_t>(n_cells_[0])};
417	    hsize_t ny {static_cast<hsize_t>(n_cells_[1])};
418	    hsize_t nz {static_cast<hsize_t>(n_cells_[2])};
419	    vector<int> out(nx * ny * nz);
420	
421	    for (int m = 0; m < nz; m++) {
422	      for (int k = 0; k < ny; k++) {
423	        for (int j = 0; j < nx; j++) {
424	          int indx1 = nx * ny * m + nx * k + j;
425	          int indx2 = nx * ny * m + nx * (ny - k - 1) + j;
426	          out[indx2] = model::universes[universes_[indx1]]->id_;
427	        }
428	      }
429	    }
430	
431	    hsize_t dims[3] {nz, ny, nx};
432	    write_int(lat_group, 3, dims, "universes", out.data(), false);
433	
434	  } else {
435	    hsize_t nx {static_cast<hsize_t>(n_cells_[0])};
436	    hsize_t ny {static_cast<hsize_t>(n_cells_[1])};
437	    vector<int> out(nx * ny);
438	
439	    for (int k = 0; k < ny; k++) {
440	      for (int j = 0; j < nx; j++) {
441	        int indx1 = nx * k + j;
442	        int indx2 = nx * (ny - k - 1) + j;
443	        out[indx2] = model::universes[universes_[indx1]]->id_;
444	      }
445	    }
446	
447	    hsize_t dims[3] {1, ny, nx};
448	    write_int(lat_group, 3, dims, "universes", out.data(), false);
449	  }
450	}
