453	// HexLattice implementation
454	//==============================================================================
455	
456	HexLattice::HexLattice(pugi::xml_node lat_node) : Lattice {lat_node}
457	{
458	  type_ = LatticeType::hex;
459	
460	  // Read the number of lattice cells in each dimension.
461	  n_rings_ = std::stoi(get_node_value(lat_node, "n_rings"));
462	  if (check_for_node(lat_node, "n_axial")) {
463	    n_axial_ = std::stoi(get_node_value(lat_node, "n_axial"));
464	    is_3d_ = true;
465	  } else {
466	    n_axial_ = 1;
467	    is_3d_ = false;
468	  }
469	
470	  // Read the lattice orientation.  Default to 'y'.
471	  if (check_for_node(lat_node, "orientation")) {
472	    std::string orientation = get_node_value(lat_node, "orientation");
473	    if (orientation == "y") {
474	      orientation_ = Orientation::y;
475	    } else if (orientation == "x") {
476	      orientation_ = Orientation::x;
477	    } else {
478	      fatal_error("Unrecognized orientation '" + orientation +
479	                  "' for lattice " + std::to_string(id_));
480	    }
481	  } else {
482	    orientation_ = Orientation::y;
483	  }
484	
485	  // Read the lattice center.
486	  std::string center_str {get_node_value(lat_node, "center")};
487	  vector<std::string> center_words {split(center_str)};
488	  if (is_3d_ && (center_words.size() != 3)) {
489	    fatal_error("A hexagonal lattice with <n_axial> must have <center> "
490	                "specified by 3 numbers.");
491	  } else if (!is_3d_ && center_words.size() != 2) {
492	    fatal_error("A hexagonal lattice without <n_axial> must have <center> "
493	                "specified by 2 numbers.");
494	  }
495	  center_[0] = stod(center_words[0]);
496	  center_[1] = stod(center_words[1]);
497	  if (is_3d_) {
498	    center_[2] = stod(center_words[2]);
499	  }
500	
501	  // Read the lattice pitches.
502	  std::string pitch_str {get_node_value(lat_node, "pitch")};
503	  vector<std::string> pitch_words {split(pitch_str)};
504	  if (is_3d_ && (pitch_words.size() != 2)) {
505	    fatal_error("A hexagonal lattice with <n_axial> must have <pitch> "
506	                "specified by 2 numbers.");
507	  } else if (!is_3d_ && (pitch_words.size() != 1)) {
508	    fatal_error("A hexagonal lattice without <n_axial> must have <pitch> "
509	                "specified by 1 number.");
510	  }
511	  pitch_[0] = stod(pitch_words[0]);
512	  if (is_3d_) {
513	    pitch_[1] = stod(pitch_words[1]);
514	  }
515	
516	  // Read the universes and make sure the correct number was specified.
517	  int n_univ = (3 * n_rings_ * n_rings_ - 3 * n_rings_ + 1) * n_axial_;
518	  std::string univ_str {get_node_value(lat_node, "universes")};
519	  vector<std::string> univ_words {split(univ_str)};
520	  if (univ_words.size() != n_univ) {
521	    fatal_error(fmt::format(
522	      "Expected {} universes for a hexagonal lattice with {} rings and {} "
523	      "axial levels but {} were specified.",
524	      n_univ, n_rings_, n_axial_, univ_words.size()));
525	  }
526	
527	  // Parse the universes.
528	  // Universes in hexagonal lattices are stored in a manner that represents
529	  // a skewed coordinate system: (x, alpha) in case of 'y' orientation
530	  // and (alpha,y) in 'x' one rather than (x, y).  There is
531	  // no obvious, direct relationship between the order of universes in the
532	  // input and the order that they will be stored in the skewed array so
533	  // the following code walks a set of index values across the skewed array
534	  // in a manner that matches the input order.  Note that i_x = 0, i_a = 0
535	  // or i_a = 0, i_y = 0 corresponds to the center of the hexagonal lattice.
536	  universes_.resize((2 * n_rings_ - 1) * (2 * n_rings_ - 1) * n_axial_, C_NONE);
537	  if (orientation_ == Orientation::y) {
538	    fill_lattice_y(univ_words);
539	  } else {
540	    fill_lattice_x(univ_words);
541	  }
542	}
543	
544	//==============================================================================
545	
546	void HexLattice::fill_lattice_x(const vector<std::string>& univ_words)
547	{
548	  int input_index = 0;
549	  for (int m = 0; m < n_axial_; m++) {
550	    // Initialize lattice indecies.
551	    int i_a = -(n_rings_ - 1);
552	    int i_y = n_rings_ - 1;
553	
554	    // Map upper region of hexagonal lattice which is found in the
555	    // first n_rings-1 rows of the input.
556	    for (int k = 0; k < n_rings_ - 1; k++) {
557	
558	      // Iterate over the input columns.
559	      for (int j = 0; j < k + n_rings_; j++) {
560	        int indx = (2 * n_rings_ - 1) * (2 * n_rings_ - 1) * m +
561	                   (2 * n_rings_ - 1) * (i_y + n_rings_ - 1) +
562	                   (i_a + n_rings_ - 1);
563	        universes_[indx] = std::stoi(univ_words[input_index]);
564	        input_index++;
565	        // Move to the next right neighbour cell
566	        i_a += 1;
567	      }
568	
569	      // Return the lattice index to the start of the current row.
570	      i_a = -(n_rings_ - 1);
571	      i_y -= 1;
572	    }
573	
574	    // Map the lower region from the centerline of cart to down side
575	    for (int k = 0; k < n_rings_; k++) {
576	      // Walk the index to the lower-right neighbor of the last row start.
577	      i_a = -(n_rings_ - 1) + k;
578	
579	      // Iterate over the input columns.
580	      for (int j = 0; j < 2 * n_rings_ - k - 1; j++) {
581	        int indx = (2 * n_rings_ - 1) * (2 * n_rings_ - 1) * m +
582	                   (2 * n_rings_ - 1) * (i_y + n_rings_ - 1) +
583	                   (i_a + n_rings_ - 1);
584	        universes_[indx] = std::stoi(univ_words[input_index]);
585	        input_index++;
586	        // Move to the next right neighbour cell
587	        i_a += 1;
588	      }
589	
590	      // Return lattice index to start of current row.
591	      i_y -= 1;
592	    }
593	  }
594	}
595	
596	//==============================================================================
597	
598	void HexLattice::fill_lattice_y(const vector<std::string>& univ_words)
599	{
600	  int input_index = 0;
601	  for (int m = 0; m < n_axial_; m++) {
602	    // Initialize lattice indecies.
603	    int i_x = 1;
604	    int i_a = n_rings_ - 1;
605	
606	    // Map upper triangular region of hexagonal lattice which is found in the
607	    // first n_rings-1 rows of the input.
608	    for (int k = 0; k < n_rings_ - 1; k++) {
609	      // Walk the index to lower-left neighbor of last row start.
610	      i_x -= 1;
611	
612	      // Iterate over the input columns.
613	      for (int j = 0; j < k + 1; j++) {
614	        int indx = (2 * n_rings_ - 1) * (2 * n_rings_ - 1) * m +
615	                   (2 * n_rings_ - 1) * (i_a + n_rings_ - 1) +
616	                   (i_x + n_rings_ - 1);
617	        universes_[indx] = std::stoi(univ_words[input_index]);
618	        input_index++;
619	        // Walk the index to the right neighbor (which is not adjacent).
620	        i_x += 2;
621	        i_a -= 1;
622	      }
623	
624	      // Return the lattice index to the start of the current row.
625	      i_x -= 2 * (k + 1);
626	      i_a += (k + 1);
627	    }
628	
629	    // Map the middle square region of the hexagonal lattice which is found in
630	    // the next 2*n_rings-1 rows of the input.
631	    for (int k = 0; k < 2 * n_rings_ - 1; k++) {
632	      if ((k % 2) == 0) {
633	        // Walk the index to the lower-left neighbor of the last row start.
634	        i_x -= 1;
635	      } else {
636	        // Walk the index to the lower-right neighbor of the last row start.
637	        i_x += 1;
638	        i_a -= 1;
639	      }
640	
641	      // Iterate over the input columns.
642	      for (int j = 0; j < n_rings_ - (k % 2); j++) {
643	        int indx = (2 * n_rings_ - 1) * (2 * n_rings_ - 1) * m +
644	                   (2 * n_rings_ - 1) * (i_a + n_rings_ - 1) +
645	                   (i_x + n_rings_ - 1);
646	        universes_[indx] = std::stoi(univ_words[input_index]);
647	        input_index++;
648	        // Walk the index to the right neighbor (which is not adjacent).
649	        i_x += 2;
650	        i_a -= 1;
651	      }
652	
653	      // Return the lattice index to the start of the current row.
654	      i_x -= 2 * (n_rings_ - (k % 2));
655	      i_a += n_rings_ - (k % 2);
656	    }
657	
658	    // Map the lower triangular region of the hexagonal lattice.
659	    for (int k = 0; k < n_rings_ - 1; k++) {
660	      // Walk the index to the lower-right neighbor of the last row start.
661	      i_x += 1;
662	      i_a -= 1;
663	
664	      // Iterate over the input columns.
665	      for (int j = 0; j < n_rings_ - k - 1; j++) {
666	        int indx = (2 * n_rings_ - 1) * (2 * n_rings_ - 1) * m +
667	                   (2 * n_rings_ - 1) * (i_a + n_rings_ - 1) +
668	                   (i_x + n_rings_ - 1);
669	        universes_[indx] = std::stoi(univ_words[input_index]);
670	        input_index++;
671	        // Walk the index to the right neighbor (which is not adjacent).
672	        i_x += 2;
673	        i_a -= 1;
674	      }
675	
676	      // Return lattice index to start of current row.
677	      i_x -= 2 * (n_rings_ - k - 1);
678	      i_a += n_rings_ - k - 1;
679	    }
680	  }
681	}
