734	//==============================================================================
735	
736	std::pair<double, array<int, 3>> HexLattice::distance(
737	  Position r, Direction u, const array<int, 3>& i_xyz) const
738	{
739	  // Short description of the direction vectors used here.  The beta, gamma, and
740	  // delta vectors point towards the flat sides of each hexagonal tile.
741	  // Y - orientation:
742	  //   basis0 = (1, 0)
743	  //   basis1 = (-1/sqrt(3), 1)   = +120 degrees from basis0
744	  //   beta   = (sqrt(3)/2, 1/2)  = +30 degrees from basis0
745	  //   gamma  = (sqrt(3)/2, -1/2) = -60 degrees from beta
746	  //   delta  = (0, 1)            = +60 degrees from beta
747	  // X - orientation:
748	  //   basis0 = (1/sqrt(3), -1)
749	  //   basis1 = (0, 1)            = +120 degrees from basis0
750	  //   beta   = (1, 0)            = +30 degrees from basis0
751	  //   gamma  = (1/2, -sqrt(3)/2) = -60 degrees from beta
752	  //   delta  = (1/2, sqrt(3)/2)  = +60 degrees from beta
753	  // The z-axis is considered separately.
754	  double beta_dir;
755	  double gamma_dir;
756	  double delta_dir;
757	  if (orientation_ == Orientation::y) {
758	    beta_dir = u.x * std::sqrt(3.0) / 2.0 + u.y / 2.0;
759	    gamma_dir = u.x * std::sqrt(3.0) / 2.0 - u.y / 2.0;
760	    delta_dir = u.y;
761	  } else {
762	    beta_dir = u.x;
763	    gamma_dir = u.x / 2.0 - u.y * std::sqrt(3.0) / 2.0;
764	    delta_dir = u.x / 2.0 + u.y * std::sqrt(3.0) / 2.0;
765	  }
766	
767	  // Note that hexagonal lattice distance calculations are performed
768	  // using the particle's coordinates relative to the neighbor lattice
769	  // cells, not relative to the particle's current cell.  This is done
770	  // because there is significant disagreement between neighboring cells
771	  // on where the lattice boundary is due to finite precision issues.
772	
773	  // beta direction
774	  double d {INFTY};
775	  array<int, 3> lattice_trans;
776	  double edge = -copysign(0.5 * pitch_[0], beta_dir); // Oncoming edge
777	  Position r_t;
778	  if (beta_dir > 0) {
779	    const array<int, 3> i_xyz_t {i_xyz[0] + 1, i_xyz[1], i_xyz[2]};
780	    r_t = get_local_position(r, i_xyz_t);
781	  } else {
782	    const array<int, 3> i_xyz_t {i_xyz[0] - 1, i_xyz[1], i_xyz[2]};
783	    r_t = get_local_position(r, i_xyz_t);
784	  }
785	  double beta;
786	  if (orientation_ == Orientation::y) {
787	    beta = r_t.x * std::sqrt(3.0) / 2.0 + r_t.y / 2.0;
788	  } else {
789	    beta = r_t.x;
790	  }
791	  if ((std::abs(beta - edge) > FP_PRECISION) && beta_dir != 0) {
792	    d = (edge - beta) / beta_dir;
793	    if (beta_dir > 0) {
794	      lattice_trans = {1, 0, 0};
795	    } else {
796	      lattice_trans = {-1, 0, 0};
797	    }
798	  }
799	
800	  // gamma direction
801	  edge = -copysign(0.5 * pitch_[0], gamma_dir);
802	  if (gamma_dir > 0) {
803	    const array<int, 3> i_xyz_t {i_xyz[0] + 1, i_xyz[1] - 1, i_xyz[2]};
804	    r_t = get_local_position(r, i_xyz_t);
805	  } else {
806	    const array<int, 3> i_xyz_t {i_xyz[0] - 1, i_xyz[1] + 1, i_xyz[2]};
807	    r_t = get_local_position(r, i_xyz_t);
808	  }
809	  double gamma;
810	  if (orientation_ == Orientation::y) {
811	    gamma = r_t.x * std::sqrt(3.0) / 2.0 - r_t.y / 2.0;
812	  } else {
813	    gamma = r_t.x / 2.0 - r_t.y * std::sqrt(3.0) / 2.0;
814	  }
815	  if ((std::abs(gamma - edge) > FP_PRECISION) && gamma_dir != 0) {
816	    double this_d = (edge - gamma) / gamma_dir;
817	    if (this_d < d) {
818	      if (gamma_dir > 0) {
819	        lattice_trans = {1, -1, 0};
820	      } else {
821	        lattice_trans = {-1, 1, 0};
822	      }
823	      d = this_d;
824	    }
825	  }
826	
827	  // delta direction
828	  edge = -copysign(0.5 * pitch_[0], delta_dir);
829	  if (delta_dir > 0) {
830	    const array<int, 3> i_xyz_t {i_xyz[0], i_xyz[1] + 1, i_xyz[2]};
831	    r_t = get_local_position(r, i_xyz_t);
832	  } else {
833	    const array<int, 3> i_xyz_t {i_xyz[0], i_xyz[1] - 1, i_xyz[2]};
834	    r_t = get_local_position(r, i_xyz_t);
835	  }
836	  double delta;
837	  if (orientation_ == Orientation::y) {
838	    delta = r_t.y;
839	  } else {
840	    delta = r_t.x / 2.0 + r_t.y * std::sqrt(3.0) / 2.0;
841	  }
842	  if ((std::abs(delta - edge) > FP_PRECISION) && delta_dir != 0) {
843	    double this_d = (edge - delta) / delta_dir;
844	    if (this_d < d) {
845	      if (delta_dir > 0) {
846	        lattice_trans = {0, 1, 0};
847	      } else {
848	        lattice_trans = {0, -1, 0};
849	      }
850	      d = this_d;
851	    }
852	  }
853	
854	  // Top and bottom sides
855	  if (is_3d_) {
856	    double z = r.z;
857	    double z0 {copysign(0.5 * pitch_[1], u.z)};
858	    if ((std::abs(z - z0) > FP_PRECISION) && u.z != 0) {
859	      double this_d = (z0 - z) / u.z;
860	      if (this_d < d) {
861	        d = this_d;
862	        if (u.z > 0) {
863	          lattice_trans = {0, 0, 1};
864	        } else {
865	          lattice_trans = {0, 0, -1};
866	        }
867	        d = this_d;
868	      }
869	    }
870	  }
871	
872	  return {d, lattice_trans};
873	}
