875	//==============================================================================
876	
877	void HexLattice::get_indices(
878	  Position r, Direction u, array<int, 3>& result) const
879	{
880	  // Offset the xyz by the lattice center.
881	  Position r_o {r.x - center_.x, r.y - center_.y, r.z};
882	  if (is_3d_) {
883	    r_o.z -= center_.z;
884	  }
885	
886	  // Index the z direction, accounting for coincidence
887	  result[2] = 0;
888	  if (is_3d_) {
889	    double iz_ {r_o.z / pitch_[1] + 0.5 * n_axial_};
890	    long iz_close {std::lround(iz_)};
891	    if (coincident(iz_, iz_close)) {
892	      result[2] = (u.z > 0) ? iz_close : iz_close - 1;
893	    } else {
894	      result[2] = std::floor(iz_);
895	    }
896	  }
897	
898	  if (orientation_ == Orientation::y) {
899	    // Convert coordinates into skewed bases.  The (x, alpha) basis is used to
900	    // find the index of the global coordinates to within 4 cells.
901	    double alpha = r_o.y - r_o.x / std::sqrt(3.0);
902	    result[0] = std::floor(r_o.x / (0.5 * std::sqrt(3.0) * pitch_[0]));
903	    result[1] = std::floor(alpha / pitch_[0]);
904	  } else {
905	    // Convert coordinates into skewed bases.  The (alpha, y) basis is used to
906	    // find the index of the global coordinates to within 4 cells.
907	    double alpha = r_o.y - r_o.x * std::sqrt(3.0);
908	    result[0] = std::floor(-alpha / (std::sqrt(3.0) * pitch_[0]));
909	    result[1] = std::floor(r_o.y / (0.5 * std::sqrt(3.0) * pitch_[0]));
910	  }
911	
912	  // Add offset to indices (the center cell is (i1, i2) = (0, 0) but
913	  // the array is offset so that the indices never go below 0).
914	  result[0] += n_rings_ - 1;
915	  result[1] += n_rings_ - 1;
916	
917	  // Calculate the (squared) distance between the particle and the centers of
918	  // the four possible cells.  Regular hexagonal tiles form a Voronoi
919	  // tessellation so the xyz should be in the hexagonal cell that it is closest
920	  // to the center of.  This method is used over a method that uses the
921	  // remainders of the floor divisions above because it provides better finite
922	  // precision performance.  Squared distances are used because they are more
923	  // computationally efficient than normal distances.
924	
925	  // COINCIDENCE CHECK
926	  // if a distance to center, d, is within the coincidence tolerance of the
927	  // current minimum distance, d_min, the particle is on an edge or vertex.
928	  // In this case, the dot product of the position vector and direction vector
929	  // for the current indices, dp, and the dot product for the currently selected
930	  // indices, dp_min, are compared. The cell which the particle is moving into
931	  // is kept (i.e. the cell with the lowest dot product as the vectors will be
932	  // completely opposed if the particle is moving directly toward the center of
933	  // the cell).
934	  int i1_chg;
935	  int i2_chg;
936	  double d_min {INFTY};
937	  double dp_min {INFTY};
938	  for (int i = 0; i < 2; i++) {
939	    for (int j = 0; j < 2; j++) {
940	      // get local coordinates
941	      const array<int, 3> i_xyz {result[0] + j, result[1] + i, 0};
942	      Position r_t = get_local_position(r, i_xyz);
943	      // calculate distance
944	      double d = r_t.x * r_t.x + r_t.y * r_t.y;
945	      // check for coincidence. Because the numerical error incurred
946	      // in hex geometry is higher than other geometries, the relative
947	      // coincidence is checked here so that coincidence is successfully
948	      // detected on large hex lattice with particles far from the origin
949	      // which have rounding errors larger than the FP_COINCIDENT thresdhold.
950	      bool on_boundary = coincident(1.0, d_min / d);
951	      if (d < d_min || on_boundary) {
952	        // normalize r_t and find dot product
953	        r_t /= std::sqrt(d);
954	        double dp = u.x * r_t.x + u.y * r_t.y;
955	        // do not update values if particle is on a
956	        // boundary and not moving into this cell
957	        if (on_boundary && dp > dp_min)
958	          continue;
959	        // update values
960	        d_min = d;
961	        i1_chg = j;
962	        i2_chg = i;
963	        dp_min = dp;
964	      }
965	    }
966	  }
967	
968	  // update outgoing indices
969	  result[0] += i1_chg;
970	  result[1] += i2_chg;
971	}
