973	int HexLattice::get_flat_index(const array<int, 3>& i_xyz) const
974	{
975	  return (2 * n_rings_ - 1) * (2 * n_rings_ - 1) * i_xyz[2] +
976	         (2 * n_rings_ - 1) * i_xyz[1] + i_xyz[0];
977	}
