1196	
1197	void read_lattices(pugi::xml_node node)
1198	{
1199	  for (pugi::xml_node lat_node : node.children("lattice")) {
1200	    model::lattices.push_back(make_unique<RectLattice>(lat_node));
1201	  }
1202	  for (pugi::xml_node lat_node : node.children("hex_lattice")) {
1203	    model::lattices.push_back(make_unique<HexLattice>(lat_node));
1204	  }
1205	
1206	  // Fill the lattice map.
1207	  for (int i_lat = 0; i_lat < model::lattices.size(); i_lat++) {
1208	    int id = model::lattices[i_lat]->id_;
1209	    auto in_map = model::lattice_map.find(id);
1210	    if (in_map == model::lattice_map.end()) {
1211	      model::lattice_map[id] = i_lat;
1212	    } else {
1213	      fatal_error(
1214	        fmt::format("Two or more lattices use the same unique ID: {}", id));
1215	    }
1216	  }
1217	}
