35	bool check_cell_overlap(GeometryState& p, bool error)
36	{
37	  int n_coord = p.n_coord();
38	
39	  // Loop through each coordinate level
40	  for (int j = 0; j < n_coord; j++) {
41	    Universe& univ = *model::universes[p.coord(j).universe()];
42	
43	    // Loop through each cell on this level
44	    for (auto index_cell : univ.cells_) {
45	      Cell& c = *model::cells[index_cell];
46	      if (c.contains(p.coord(j).r(), p.coord(j).u(), p.surface())) {
47	        if (index_cell != p.coord(j).cell()) {
48	          if (error) {
49	            fatal_error(
50	              fmt::format("Overlapping cells detected: {}, {} on universe {}",
51	                c.id_, model::cells[p.coord(j).cell()]->id_, univ.id_));
52	          }
53	          return true;
54	        }
55	#pragma omp atomic
56	        ++model::overlap_check_count[index_cell];
57	      }
58	    }
59	  }
60	
61	  return false;
62	}
