101	
102	bool find_cell_inner(
103	  GeometryState& p, const NeighborList* neighbor_list, bool verbose)
104	{
105	  // Find which cell of this universe the particle is in.  Use the neighbor list
106	  // to shorten the search if one was provided.
107	  bool found = false;
108	  int32_t i_cell = C_NONE;
109	  if (neighbor_list) {
110	    for (auto it = neighbor_list->cbegin(); it != neighbor_list->cend(); ++it) {
111	      i_cell = *it;
112	
113	      // Make sure the search cell is in the same universe.
114	      int i_universe = p.lowest_coord().universe();
115	      if (model::cells[i_cell]->universe_ != i_universe)
116	        continue;
117	
118	      // Check if this cell contains the particle.
119	      Position r {p.r_local()};
120	      Direction u {p.u_local()};
121	      auto surf = p.surface();
122	      if (model::cells[i_cell]->contains(r, u, surf)) {
123	        p.lowest_coord().cell() = i_cell;
124	        found = true;
125	        break;
126	      }
127	    }
128	
129	    // If we're attempting a neighbor list search and fail, we
130	    // now know we should return false. This will trigger an
131	    // exhaustive search from neighbor_list_find_cell and make
132	    // the result from that be appended to the neighbor list.
133	    if (!found) {
134	      return found;
135	    }
136	  }
137	
138	  // Check successively lower coordinate levels until finding material fill
139	  for (;; ++p.n_coord()) {
140	    // If we did not attempt to use neighbor lists, i_cell is still C_NONE.  In
141	    // that case, we should now do an exhaustive search to find the right value
142	    // of i_cell.
143	    //
144	    // Alternatively, neighbor list searches could have succeeded, but we found
145	    // that the fill of the neighbor cell was another universe. As such, in the
146	    // code below this conditional, we set i_cell back to C_NONE to indicate
147	    // that.
148	    if (i_cell == C_NONE) {
149	      int i_universe = p.lowest_coord().universe();
150	      const auto& univ {model::universes[i_universe]};
151	      found = univ->find_cell(p);
152	    }
153	
154	    if (!found) {
155	      return found;
156	    }
157	    i_cell = p.lowest_coord().cell();
158	
159	    // Announce the cell that the particle is entering.
160	    if (found && verbose) {
161	      auto msg = fmt::format("    Entering cell {}", model::cells[i_cell]->id_);
162	      write_message(msg, 1);
163	    }
164	
165	    Cell& c {*model::cells[i_cell]};
166	    if (c.type_ == Fill::MATERIAL) {
167	      // Found a material cell which means this is the lowest coord level.
168	
169	      p.cell_instance() = 0;
170	      // Find the distribcell instance number.
171	      if (c.distribcell_index_ >= 0) {
172	        p.cell_instance() = cell_instance_at_level(p, p.n_coord() - 1);
173	      }
174	
175	      // Set the material, temperature and density multiplier.
176	      p.material_last() = p.material();
177	      p.material() = c.material(p.cell_instance());
178	      p.sqrtkT_last() = p.sqrtkT();
179	      p.sqrtkT() = c.sqrtkT(p.cell_instance());
180	      p.density_mult_last() = p.density_mult();
181	      p.density_mult() = c.density_mult(p.cell_instance());
182	
183	      return true;
184	
185	    } else if (c.type_ == Fill::UNIVERSE) {
186	      //========================================================================
187	      //! Found a lower universe, update this coord level then search the next.
188	
189	      // Set the lower coordinate level universe.
190	      auto& coord {p.coord(p.n_coord())};
191	      coord.universe() = c.fill_;
192	
193	      // Set the position and direction.
194	      coord.r() = p.r_local();
195	      coord.u() = p.u_local();
196	
197	      // Apply translation.
198	      coord.r() -= c.translation_;
199	
200	      // Apply rotation.
201	      if (!c.rotation_.empty()) {
202	        coord.rotate(c.rotation_);
203	      }
204	
205	    } else if (c.type_ == Fill::LATTICE) {
206	      //========================================================================
207	      //! Found a lower lattice, update this coord level then search the next.
208	
209	      Lattice& lat {*model::lattices[c.fill_]};
210	
211	      // Set the position and direction.
212	      auto& coord {p.coord(p.n_coord())};
213	      coord.r() = p.r_local();
214	      coord.u() = p.u_local();
215	
216	      // Apply translation.
217	      coord.r() -= c.translation_;
218	
219	      // Apply rotation.
220	      if (!c.rotation_.empty()) {
221	        coord.rotate(c.rotation_);
222	      }
223	
224	      // Determine lattice indices.
225	      auto& i_xyz {coord.lattice_index()};
226	      lat.get_indices(coord.r(), coord.u(), i_xyz);
227	
228	      // Get local position in appropriate lattice cell
229	      coord.r() = lat.get_local_position(coord.r(), i_xyz);
230	
231	      // Set lattice indices.
232	      coord.lattice() = c.fill_;
233	
234	      // Set the lower coordinate level universe.
235	      if (lat.are_valid_indices(i_xyz)) {
236	        coord.universe() = lat[i_xyz];
237	      } else {
238	        if (lat.outer_ != NO_OUTER_UNIVERSE) {
239	          coord.universe() = lat.outer_;
240	        } else {
241	          p.mark_as_lost(fmt::format(
242	            "Particle {} left lattice {}, but it has no outer definition.",
243	            p.id(), lat.id_));
244	        }
245	      }
246	    }
247	    i_cell = C_NONE; // trip non-neighbor cell search at next iteration
248	    found = false;
249	  }
250	
251	  return found;
252	}
