255	
256	bool neighbor_list_find_cell(GeometryState& p, bool verbose)
257	{
258	
259	  // Reset all the deeper coordinate levels.
260	  for (int i = p.n_coord(); i < model::n_coord_levels; i++) {
261	    p.coord(i).reset();
262	  }
263	
264	  // Get the cell this particle was in previously.
265	  auto coord_lvl = p.n_coord() - 1;
266	  auto i_cell = p.coord(coord_lvl).cell();
267	  Cell& c {*model::cells[i_cell]};
268	
269	  // Search for the particle in that cell's neighbor list.  Return if we
270	  // found the particle.
271	  bool found = find_cell_inner(p, &c.neighbors_, verbose);
272	  if (found)
273	    return found;
274	
275	  // The particle could not be found in the neighbor list.  Try searching all
276	  // cells in this universe, and update the neighbor list if we find a new
277	  // neighboring cell.
278	  found = find_cell_inner(p, nullptr, verbose);
279	  if (found)
280	    c.neighbors_.push_back(p.coord(coord_lvl).cell());
281	  return found;
282	}
