284	bool exhaustive_find_cell(GeometryState& p, bool verbose)
285	{
286	  int i_universe = p.lowest_coord().universe();
287	  if (i_universe == C_NONE) {
288	    p.coord(0).universe() = model::root_universe;
289	    p.n_coord() = 1;
290	    i_universe = model::root_universe;
291	  }
292	  // Reset all the deeper coordinate levels.
293	  for (int i = p.n_coord(); i < model::n_coord_levels; i++) {
294	    p.coord(i).reset();
295	  }
296	  return find_cell_inner(p, nullptr, verbose);
297	}
