360	
361	BoundaryInfo distance_to_boundary(GeometryState& p)
362	{
363	  BoundaryInfo info;
364	  double d_lat = INFINITY;
365	  double d_surf = INFINITY;
366	  int32_t level_surf_cross;
367	  array<int, 3> level_lat_trans {};
368	
369	  // Loop over each coordinate level.
370	  for (int i = 0; i < p.n_coord(); i++) {
371	    const auto& coord {p.coord(i)};
372	    const Position& r {coord.r()};
373	    const Direction& u {coord.u()};
374	    Cell& c {*model::cells[coord.cell()]};
375	
376	    // Find the oncoming surface in this cell and the distance to it.
377	    auto surface_distance = c.distance(r, u, p.surface(), &p);
378	    d_surf = surface_distance.first;
379	    level_surf_cross = surface_distance.second;
380	
381	    // Find the distance to the next lattice tile crossing.
382	    if (coord.lattice() != C_NONE) {
383	      auto& lat {*model::lattices[coord.lattice()]};
384	      // TODO: refactor so both lattice use the same position argument (which
385	      // also means the lat.type attribute can be removed)
386	      std::pair<double, array<int, 3>> lattice_distance;
387	      switch (lat.type_) {
388	      case LatticeType::rect:
389	        lattice_distance = lat.distance(r, u, coord.lattice_index());
390	        break;
391	      case LatticeType::hex:
392	        auto& cell_above {model::cells[p.coord(i - 1).cell()]};
393	        Position r_hex {p.coord(i - 1).r()};
394	        r_hex -= cell_above->translation_;
395	        if (coord.rotated()) {
396	          r_hex = r_hex.rotate(cell_above->rotation_);
397	        }
398	        r_hex.z = coord.r().z;
399	        lattice_distance = lat.distance(r_hex, u, coord.lattice_index());
400	        break;
401	      }
402	      d_lat = lattice_distance.first;
403	      level_lat_trans = lattice_distance.second;
404	
405	      if (d_lat < 0) {
406	        p.mark_as_lost(fmt::format("Particle {} had a negative distance "
407	                                   "to a lattice boundary.",
408	          p.id()));
409	      }
410	    }
411	
412	    // If the boundary on this coordinate level is coincident with a boundary on
413	    // a higher level then we need to make sure that the higher level boundary
414	    // is selected.  This logic must consider floating point precision.
415	    double& d = info.distance();
416	    if (d_surf < d_lat - FP_COINCIDENT) {
417	      if (d == INFINITY || (d - d_surf) / d >= FP_REL_PRECISION) {
418	        // Update closest distance
419	        d = d_surf;
420	
421	        // If the cell is not simple, it is possible that both the negative and
422	        // positive half-space were given in the region specification. Thus, we
423	        // have to explicitly check which half-space the particle would be
424	        // traveling into if the surface is crossed
425	        if (c.is_simple() || d == INFTY) {
426	          info.surface() = level_surf_cross;
427	        } else {
428	          Position r_hit = r + d_surf * u;
429	          Surface& surf {*model::surfaces[std::abs(level_surf_cross) - 1]};
430	          Direction norm = surf.normal(r_hit);
431	          if (u.dot(norm) > 0) {
432	            info.surface() = std::abs(level_surf_cross);
433	          } else {
434	            info.surface() = -std::abs(level_surf_cross);
435	          }
436	        }
437	
438	        info.lattice_translation()[0] = 0;
439	        info.lattice_translation()[1] = 0;
440	        info.lattice_translation()[2] = 0;
441	        info.coord_level() = i + 1;
442	      }
443	    } else {
444	      if (d == INFINITY || (d - d_lat) / d >= FP_REL_PRECISION) {
445	        d = d_lat;
446	        info.surface() = SURFACE_NONE;
447	        info.lattice_translation() = level_lat_trans;
448	        info.coord_level() = i + 1;
449	      }
450	    }
451	  }
452	  return info;
453	}
